    width = min(sep, w - sep - 1)

    left = [grid[r][:width] for r in range(h)]
    right = [grid[r][sep + 1:sep + 1 + width] for r in range(h)]

    def background(panel):
        counts = {}
        for row in panel:
            for value in row:
                counts[value] = counts.get(value, 0) + 1
        return max(counts, key=counts.get)

    lb, rb = background(left), background(right)
    return [
        [3 if left[r][c] != lb and right[r][c] != rb else 2
         for c in range(width)]
